/** Types of the per-version schemas generated by tools/idd2json.py. */

export interface FieldSchema {
  name: string;
  /** alpha, real, integer, choice, object-list, external-list, node */
  type: string;
  required?: boolean;
  units?: string;
  unitsBasedOnField?: string;
  default?: string | number;
  min?: number;
  max?: number;
  minExclusive?: boolean;
  maxExclusive?: boolean;
  keys?: string[];
  reference?: string[];
  objectList?: string[];
  externalList?: string[];
  referenceClassName?: string[];
  autosizable?: boolean;
  autocalculatable?: boolean;
  deprecated?: boolean;
  retainCase?: boolean;
  /** Name template for extensible fields, e.g. "Vertex {n} X-coordinate". */
  tpl?: string;
  /** Number used in the first group when it is not 1. */
  n0?: number;
}

export interface ClassSchema {
  name: string;
  group?: string;
  unique?: boolean;
  required?: boolean;
  minFields?: number;
  format?: string;
  obsolete?: string | boolean;
  refClass?: string[];
  /** The fields from `start` on repeat in groups of `size` (only the first group is listed). */
  extensible?: { size: number; start: number };
  fields: FieldSchema[];
}

export interface Schema {
  version: string;
  build: string | null;
  groups: string[];
  /** Keyed by lowercase class name. */
  classes: Record<string, ClassSchema>;
}

export interface SchemaIndex {
  versions: string[];
}

export interface ClassDocs {
  memo?: string;
  /** Notes by field index (first extensible group only). */
  notes?: Record<string, string>;
}

export interface SchemaDocs {
  version: string;
  classes: Record<string, ClassDocs>;
}
